import React from "react";
import { render, fireEvent, screen } from "@testing-library/react";
import { composeStories } from "@storybook/react";
import { axe } from "jest-axe";
import ConsoleSpy from "../../lib/tests/ConsoleSpy";
import * as stories from "./Radio.stories";
import Radio from ".";

const { Basic } = composeStories(stories) as any;

describe("Radio component", () => {
  let consoleSpy = ConsoleSpy();

  it("pass A11Y", async () => {
    const { container } = render(<Basic />);
    const results = await axe(container);
    expect(results).toHaveNoViolations();
  });

  it("should get checked when clicking on label", () => {
    render(<Radio label="radio" />);
    fireEvent.click(screen.getByText("radio"));
    expect(screen.getByRole("radio")).toBeChecked();
  });

  it("should call onChange when uncontrolled", () => {
    const onChange = jest.fn();
    render(<Radio onChange={onChange} label="radio" />);
    fireEvent.click(screen.getByText("radio"));
    expect(onChange).toHaveBeenCalledTimes(1);
  });

  it("should call onChange when controlled", () => {
    consoleSpy.log.mockRestore();
    const onChange = jest.fn();
    render(<Radio onChange={onChange} label="radio" />);
    fireEvent.click(screen.getByText("radio"));
    expect(onChange).toHaveBeenCalledTimes(1);
  });

  it("passes through props to the input element", () => {
    render(<Radio data-testid="radio" />);
    expect(screen.queryByRole("radio")).toHaveAttribute("data-testid", "radio");
  });
});
